   388→    margin-top: calc(var(--spacing) * 6);
   389→  }
   390→  .typography details:not(.not-typography details) summary {
   391→    cursor: pointer;
   392→    font-weight: 600;
   393→    margin-top: calc(var(--spacing) * 6);
   394→    letter-spacing: var(--tracking-tight);
   395→  }
   396→  .typography details:not(.not-typography details) p:first-of-type {
   397→    margin-top: calc(var(--spacing) * 2);
