   410→      line-height: var(--text-5xl--line-height);
   411→    }
   412→  }
   413→}
   414→
   415→@layer utilities {
   416→  .text-gradient {
   417→    @apply bg-clip-text text-transparent;
   418→  }
   419→
   420→  .bg-grid {
   421→    --bg-grid-color: rgba(255, 255, 255, 0.05);
   422→    background-color: transparent;
   423→    background-image:
   424→      linear-gradient(90deg, var(--bg-grid-color) 1px, transparent 1px),
   425→      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
   426→    background-size: 64px 64px;
