   479→      radial-gradient(circle at 90% 90%, rgba(255, 51, 102, 0.06) 0%, transparent 40%);
   480→  }
   481→
   482→  .mesh-gradient-subtle {
   483→    background:
   484→      radial-gradient(circle at 10% 10%, rgba(0, 255, 170, 0.04) 0%, transparent 40%),
   485→      radial-gradient(circle at 90% 90%, rgba(255, 51, 102, 0.03) 0%, transparent 40%);
   486→  }
   487→
   488→  /* Glow effects */
   489→  .glow-emerald {
