   495→  }
   496→
   497→  .glow-emerald-lg {
   498→    box-shadow: 0 0 40px rgba(0, 255, 170, 0.2);
   499→  }
   500→
   501→  .glow-crimson-lg {
   502→    box-shadow: 0 0 40px rgba(255, 51, 102, 0.2);
   503→  }
   504→
   505→  /* Text colors for accents */
   506→  .text-emerald {
   507→    color: var(--accent-emerald);
   508→  }
   509→
   510→  .text-crimson {
   511→    color: var(--accent-crimson);
   512→  }
   513→
   514→  /* Border colors for accents */
   515→  .border-emerald {
   516→    border-color: var(--accent-emerald);
   517→  }
   518→
   519→  .border-crimson {
   520→    border-color: var(--accent-crimson);
   521→  }
   522→
   523→  /* Background colors for accents */
   524→  .bg-emerald {
   525→    background-color: var(--accent-emerald);
   526→  }
   527→
   528→  .bg-crimson {
   529→    background-color: var(--accent-crimson);
   530→  }
   531→
   532→  /* Hover animations */
   533→  .hover-lift {
   534→    transition: transform 0.2s ease, box-shadow 0.2s ease;
   535→  }
   536→
   537→  .hover-lift:hover {
   538→    transform: translateY(-2px);
   539→  }
   540→
   541→  /* Focus states with emerald glow */
   542→  .focus-emerald:focus-visible {
   543→    outline: none;
   544→    box-shadow: 0 0 0 2px var(--bg-obsidian), 0 0 0 4px rgba(0, 255, 170, 0.5);
   545→  }
   546→}
   547→
   548→/* Other styles */
   549→
   550→.citation {
   551→  position: relative;
   552→  display: inline-block;
   553→  padding: 4px;
