import type { PropsWithChildren } from "react";

export default function RouteLayout(props: PropsWithChildren) {
  return (
    <div className="relative flex min-h-full items-center justify-center bg-[var(--bg-obsidian)]">
      {/* Mesh gradient background */}
      <div className="mesh-gradient pointer-events-none absolute inset-0" />

      {/* Grid overlay */}
      <div className="bg-grid pointer-events-none absolute inset-0 opacity-30" />

      {/* Content */}
      <div className="relative z-10 px-4 py-8">{props.children}</div>
    </div>
  );
}

