  /* Scanline animation */
  @keyframes scan {
    0% {
      top: -100%;
    }
    100% {
      top: 100%;
    }
  }

  .scanline {
    position: relative;
    overflow: hidden;
  }

  .scanline::after {
    content: "";
    position: absolute;
    width: 100%;
    height: 2px;
    left: 0;
    background: linear-gradient(
      90deg,
      transparent,
      var(--accent-emerald),
      transparent
    );
    animation: scan 6s linear infinite;
    opacity: 0.4;
    pointer-events: none;
  }

  /* Locked blur for premium content */
  .locked-blur {
    filter: blur(8px);
    user-select: none;
    pointer-events: none;
  }

  /* Terminal style text */
  .terminal-text {
    font-family: var(--font-mono);
    color: var(--accent-emerald);
    text-transform: uppercase;
    letter-spacing: 0.1em;
  }

  /* Radar animation for auth pages */
  @keyframes radar-sweep {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }

  @keyframes radar-pulse {
    0%,
    100% {
      opacity: 0.3;
      transform: scale(1);
    }
    50% {
      opacity: 0.6;
      transform: scale(1.02);
    }
  }

  .radar-sweep {
    animation: radar-sweep 8s linear infinite;
  }

  .radar-pulse {
    animation: radar-pulse 4s ease-in-out infinite;
  }

  /* Glow text effects */
  .glow-text-emerald {
    text-shadow: 0 0 20px rgba(0, 255, 170, 0.5);
  }

  .glow-text-crimson {
    text-shadow: 0 0 20px rgba(255, 51, 102, 0.5);
  }

  /* Badge pulse animation */
  @keyframes badge-pulse {
    0%,
    100% {
      box-shadow: 0 0 0 0 rgba(0, 255, 170, 0.4);
    }
    50% {
      box-shadow: 0 0 0 8px rgba(0, 255, 170, 0);
    }
  }

  .badge-pulse {
    animation: badge-pulse 2s ease-in-out infinite;
  }

  /* Focus glow for inputs */
  .focus-glow-emerald:focus-visible {
    outline: none;
    border-color: rgba(0, 255, 170, 0.5);
    box-shadow: 0 0 0 3px rgba(0, 255, 170, 0.2);
  }

