  .typography kbd:not(.not-typography kbd) {
    border-radius: calc(var(--radius) - 2px);
    background-color: var(--color-muted);
    padding: calc(var(--spacing) * 0.5) calc(var(--spacing) * 1.5);
    font-size: var(--text-xs);
    line-height: var(--text-xs--line-height);
    font-weight: 600;
  }
  .typography hr {
    margin-top: calc(var(--spacing) * 10);
    margin-bottom: calc(var(--spacing) * 10);
  }
  .typography dl:not(.not-typography dl) {
    margin-top: calc(var(--spacing) * 6);
    margin-bottom: calc(var(--spacing) * 6);
  }
  .typography dl:not(.not-typography dl) dt {
    font-weight: 600;
    margin-top: calc(var(--spacing) * 6);
    letter-spacing: var(--tracking-tight);
  }
  .typography dl:not(.not-typography dl) dt:first-child {
    margin-top: 0;
  }
  .typography details:not(.not-typography details) {
    margin-top: calc(var(--spacing) * 6);
  }
  .typography details:not(.not-typography details) summary {
    cursor: pointer;
    font-weight: 600;
    margin-top: calc(var(--spacing) * 6);
    letter-spacing: var(--tracking-tight);
  }
  .typography details:not(.not-typography details) p:first-of-type {
    margin-top: calc(var(--spacing) * 2);
  }
  .typography mark:not(.not-typography mark) {
    background-color: var(--color-yellow-300);
  }
  .typography small:not(.not-typography small) {
    font-size: var(--text-xs);
    line-height: 1;
  }

  @media (min-width: 1024px) {
    .typography h1:not(.not-typography h1) {
      font-size: var(--text-5xl);
      line-height: var(--text-5xl--line-height);
    }
  }
}

@layer utilities {
  .text-gradient {
    @apply bg-clip-text text-transparent;
  }

  .bg-grid {
    --bg-grid-color: rgba(255, 255, 255, 0.05);
    background-color: transparent;
    background-image:
      linear-gradient(90deg, var(--bg-grid-color) 1px, transparent 1px),
      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
    background-size: 64px 64px;
  }

  /* Glassmorphism utilities */
  .glass {
    backdrop-filter: blur(12px);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
  }

  .glass-sm {
    backdrop-filter: blur(8px);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
  }

  .glass-lg {
    backdrop-filter: blur(20px);
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--glass-border);
  }

  .hyper-border {
    background: var(--glass-bg);
    backdrop-filter: blur(12px);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    transition: border-color 0.2s ease;
  }

  .hyper-border:hover {
    border-color: var(--glass-border-hover);
  }

  /* Grain texture overlay */
  .grain-overlay {
    position: relative;
  }

  .grain-overlay::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
    opacity: 0.04;
    pointer-events: none;
    z-index: 1;
  }

  /* Mesh gradient backgrounds */
  .mesh-gradient {
    background:
      radial-gradient(circle at 10% 10%, rgba(0, 255, 170, 0.08) 0%, transparent 40%),
      radial-gradient(circle at 90% 90%, rgba(255, 51, 102, 0.06) 0%, transparent 40%);
  }

  .mesh-gradient-subtle {
    background:
      radial-gradient(circle at 10% 10%, rgba(0, 255, 170, 0.04) 0%, transparent 40%),
      radial-gradient(circle at 90% 90%, rgba(255, 51, 102, 0.03) 0%, transparent 40%);
  }

  /* Glow effects */
  .glow-emerald {
    box-shadow: 0 0 20px rgba(0, 255, 170, 0.15);
  }

  .glow-crimson {
    box-shadow: 0 0 20px rgba(255, 51, 102, 0.15);
  }

  .glow-emerald-lg {
    box-shadow: 0 0 40px rgba(0, 255, 170, 0.2);
  }

  .glow-crimson-lg {
    box-shadow: 0 0 40px rgba(255, 51, 102, 0.2);
  }

  /* Text colors for accents */
  .text-emerald {
    color: var(--accent-emerald);
  }

  .text-crimson {
    color: var(--accent-crimson);
  }

  /* Border colors for accents */
  .border-emerald {
    border-color: var(--accent-emerald);
  }

  .border-crimson {
    border-color: var(--accent-crimson);
  }

  /* Background colors for accents */
  .bg-emerald {
    background-color: var(--accent-emerald);
  }

  .bg-crimson {
    background-color: var(--accent-crimson);
  }

  /* Hover animations */
  .hover-lift {
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }

  .hover-lift:hover {
    transform: translateY(-2px);
  }

  /* Focus states with emerald glow */
  .focus-emerald:focus-visible {
    outline: none;
    box-shadow: 0 0 0 2px var(--bg-obsidian), 0 0 0 4px rgba(0, 255, 170, 0.5);
  }
}

/* Other styles */

.citation {
  position: relative;
  display: inline-block;
  padding: 4px;
  border-radius: 0.5rem;
  color: var(--foreground);
  font-style: italic;
  --gap: -16px;
}

.citation::before {
  content: "";
  font-size: 3rem;
  position: absolute;
  top: -12px;
  left: -12px;
  line-height: 1;
  color: var(--primary);
}

.citation::after {
  content: "";
  font-size: 3rem;
  position: absolute;
  bottom: -16px;
  right: -4px;
  line-height: 1;
  color: var(--primary);
}

.citation strong {
  font-weight: 700;
  background: rgba(0, 255, 170, 0.2);
  display: inline;
  padding: 2px;
  margin: -2px;
}

.dot-pattern {
  background-color: var(--dot-background);
  opacity: 0.8;
  background-image: radial-gradient(
    var(--dot-color) 0.5px,
    var(--dot-background) 0.5px
  );
  background-size: var(--size, 10px) var(--size, 10px);
}

.shiki,
.shiki span {
  color: var(--shiki-dark) !important;
  background-color: var(--shiki-dark-bg) !important;
  font-style: var(--shiki-dark-font-style) !important;
  font-weight: var(--shiki-dark-font-weight) !important;
  text-decoration: var(--shiki-dark-text-decoration) !important;
}

.prose {
  code:not(pre code) {
    &::after {
      display: none;
    }
    &::before {
      display: none;
    }

    background-color: var(--muted);
    padding: calc(var(--spacing) * 1.5);
    border-radius: var(--radius);
  }
}
.chat-prose {
  h1,
  h2,
  h3 {
    font-size: 1rem !important;
  }
}

.code-example {
  & pre {
    margin: 0 !important;
  }
}

import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import type * as React from "react";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 aria-invalid:border-destructive inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium outline-none transition-all focus-visible:ring disabled:pointer-events-none disabled:opacity-50 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0 cursor-pointer",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90 focus-visible:ring-primary",
        destructive:
          "bg-destructive shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 text-white",
        outline:
          "bg-background shadow-xs hover:bg-accent hover:text-accent-foreground border",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
        invert: "bg-foreground text-background hover:bg-foreground/90",
        success: "bg-success text-success-foreground hover:bg-success/90",
        warning: "bg-warning text-warning-foreground hover:bg-warning/90",
        emerald:
          "bg-[#00ffaa] text-[#05070a] hover:bg-[#00ffaa]/90 font-semibold shadow-xs",
        crimson:
          "bg-[#ff3366] text-white hover:bg-[#ff3366]/90 font-semibold shadow-xs",
        glass:
          "bg-transparent border border-[var(--glass-border)] backdrop-blur-sm hover:border-[var(--glass-border-hover)] hover:bg-white/5",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export type ButtonProps = React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  };

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: ButtonProps) {
  const Comp = asChild ? Slot : "button";

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

import type * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const cardVariants = cva(
  "flex flex-col gap-6 rounded-xl py-6 text-card-foreground",
  {
    variants: {
      variant: {
        default: "bg-card border shadow-sm",
        hyper:
          "bg-[var(--glass-bg)] backdrop-blur-xl border border-[var(--glass-border)] hover:border-[var(--glass-border-hover)] transition-colors",
        glass:
          "bg-transparent backdrop-blur-md border border-[var(--glass-border)]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export type CardProps = React.ComponentProps<"div"> &
  VariantProps<typeof cardVariants>;

function Card({ className, variant, ...props }: CardProps) {
  return (
    <div
      data-slot="card"
      className={cn(cardVariants({ variant }), className)}
      {...props}
    />
  );
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start gap-1.5 px-6 has-[data-slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6",
        className,
      )}
      {...props}
    />
  );
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-title"
      className={cn("leading-none font-semibold", className)}
      {...props}
    />
  );
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  );
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn(
        "col-start-2 row-span-2 row-start-1 self-start justify-self-end",
        className,
      )}
      {...props}
    />
  );
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-content"
      className={cn("px-6", className)}
      {...props}
    />
  );
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn("flex items-center px-6 [.border-t]:pt-6", className)}
      {...props}
    />
  );
}

export {
  Card,
  CardHeader,
  CardFooter,
  CardTitle,
  CardAction,
  CardDescription,
  CardContent,
};

