              <Link
                key={link.href}
                href={link.href}
                onClick={() => setMobileMenuOpen(false)}
                className="rounded-lg px-4 py-3 text-sm font-medium tracking-wider uppercase text-[var(--text-secondary)] transition-colors hover:bg-[var(--glass-bg)] hover:text-[#00ffaa]"
              >
                {link.label}
              </Link>
            ))}
          </nav>
        </motion.div>
      )}
    </>
  );
}

const clamp = (number: number, min: number, max: number) =>
  Math.min(Math.max(number, min), max);

