      >
        <div className="mx-auto flex w-full max-w-7xl items-center justify-between px-4 lg:px-8">
          {/* Logo & Brand */}
          <div className="flex items-center gap-3">
            <LogoSvg
              size={28}
              onClick={() => {
                router.push("/");
              }}
            />
            <motion.p
              style={{
                scale: useTransform(
                  scrollYBoundedProgressDelayed,
                  [0, 1],
                  [1, 0.9],
                ),
