              className="flex origin-left items-center text-lg font-bold tracking-wider uppercase max-sm:hidden"
            >
              {SiteConfig.title}
            </motion.p>
          </div>

          {/* Desktop Navigation */}
          <motion.nav
            style={{
              opacity: useTransform(
                scrollYBoundedProgressDelayed,
                [0, 1],
                [1, 0],
              ),
            }}
            className="hidden items-center gap-8 md:flex"
            suppressHydrationWarning
          >
            {NAV_LINKS.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className="text-xs font-medium tracking-widest uppercase text-[var(--text-secondary)] transition-colors hover:text-[#00ffaa]"
              >
                {link.label}
              </Link>
            ))}
          </motion.nav>

          {/* Right Side Actions */}
          <div className="flex items-center gap-4">
            {/* Language Switcher Placeholder */}
            <div className="hidden text-xs font-medium tracking-wider uppercase text-[var(--text-muted)] lg:block">
              EN
            </div>

            <AuthButtonClient />

            {/* Mobile Menu Button */}
            <button
              type="button"
              className="flex items-center justify-center rounded-md p-2 text-[var(--text-secondary)] transition-colors hover:bg-[var(--glass-bg)] hover:text-white md:hidden"
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            >
              {mobileMenuOpen ? (
                <X className="size-5" />
              ) : (
                <Menu className="size-5" />
              )}
            </button>
          </div>
        </div>
      </motion.header>

      {/* Mobile Menu */}
      {mobileMenuOpen && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
