import { Loader } from "@/components/nowts/loader";
import { Typography } from "@/components/nowts/typography";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { getUser } from "@/lib/auth/auth-user";
import { SiteConfig } from "@/site-config";
import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { Suspense } from "react";
import { SignUpCredentialsForm } from "./sign-up-credentials-form";

export const metadata: Metadata = {
  title: `Sign Up | ${SiteConfig.title}`,
  description:
    "Create your account to start collecting powerful testimonials for your projects.",
};

export default async function AuthSignInPage() {
  const user = await getUser();

  if (user) {
    redirect("/");
  }

  return (
    <Card
      variant="hyper"
      className="mx-auto w-full max-w-md border-[var(--glass-border)] lg:max-w-lg lg:p-6"
    >
      <CardHeader className="flex flex-col items-center justify-center gap-1">
        <Avatar className="mb-4 rounded-sm border border-[var(--glass-border)]">
          <AvatarImage src={SiteConfig.appIcon} alt="app logo" />
          <AvatarFallback className="bg-[var(--bg-graphite)]">
            {SiteConfig.title.substring(0, 1).toUpperCase()}
          </AvatarFallback>
        </Avatar>
        <CardTitle className="font-bold">
          Sign up to {SiteConfig.title}
        </CardTitle>
        <CardDescription className="text-[var(--text-secondary)]">
          We just need a few details to get you started.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Suspense fallback={<Loader />}>
          <SignUpCredentialsForm />
        </Suspense>

        <Typography
          variant="muted"
          className="mt-4 text-xs text-[var(--text-muted)]"
        >
          You already have an account?{" "}
          <Typography
            variant="link"
            as={Link}
            href="/auth/signin"
            className="text-[#00ffaa] hover:text-[#00ffaa]/80"
          >
            Sign in
          </Typography>
        </Typography>
      </CardContent>
    </Card>
  );
}

