"use client";

import { Button } from "@/components/ui/button";
import {
  followTraderAction,
  unfollowTraderAction,
} from "@/features/follow/follow.action";
import { isActionSuccessful } from "@/lib/actions/actions-utils";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Check, Plus } from "lucide-react";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { toast } from "sonner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

type FollowButtonProps = {
  traderId: string;
  traderName: string;
  isFollowing: boolean;
  userId?: string; // Pour la query key
  variant?: "default" | "outline" | "ghost";
  size?: "default" | "sm" | "lg";
  source?: "DIRECT" | "INVITATION" | "REFERRAL";
  onFollowSuccess?: () => void;
  className?: string;
};

export const FollowButton = ({
  traderId,
  traderName,
  isFollowing,
  userId,
  variant = "default",
  size = "default",
  source = "DIRECT",
  onFollowSuccess,
  className,
}: FollowButtonProps) => {
  const router = useRouter();
  const queryClient = useQueryClient();
  const [showUnfollowDialog, setShowUnfollowDialog] = useState(false);

  // Mutation pour suivre un trader avec optimistic updates
  const followMutation = useMutation({
    mutationFn: async () => {
      const result = await followTraderAction({ traderId, source });

      if (!isActionSuccessful(result)) {
        throw new Error(result.serverError ?? "Failed to follow trader");
      }

      return result.data;
    },
    onMutate: async () => {
      // Annuler toutes les queries en cours pour éviter les conflits
      await queryClient.cancelQueries({ queryKey: ["is-following"] });

      // Snapshot de la valeur précédente (utiliser userId si fourni pour matcher la query key)
      const queryKey = userId
        ? ["is-following", userId, traderId]
        : ["is-following", traderId];
      const previousIsFollowing = queryClient.getQueryData(queryKey);

      // Optimistic update : on met à jour immédiatement l'UI
      queryClient.setQueryData(queryKey, true);

      // Retourner le context avec la valeur précédente pour le rollback
      return { previousIsFollowing, queryKey };
    },
    onSuccess: (data) => {
      toast.success(data.message);
      // Invalider les queries pour rafraîchir les données depuis le serveur
      void queryClient.invalidateQueries({ queryKey: ["traders"] });
      void queryClient.invalidateQueries({ queryKey: ["following"] });
      void queryClient.invalidateQueries({ queryKey: ["is-following"] });
      void queryClient.invalidateQueries({ queryKey: ["trader-followers"] });
      void queryClient.invalidateQueries({ queryKey: ["trader-signals"] });
      // Force Server Component revalidation
      router.refresh();
      // Call custom success handler if provided
      if (onFollowSuccess) {
        onFollowSuccess();
      }
    },
    onError: (error: Error, _variables, context) => {
      // En cas d'erreur, rollback à la valeur précédente
      if (context) {
        queryClient.setQueryData(context.queryKey, context.previousIsFollowing);
      }
      toast.error(error.message);
    },
  });

  // Mutation pour ne plus suivre un trader avec optimistic updates
  const unfollowMutation = useMutation({
    mutationFn: async () => {
      const result = await unfollowTraderAction({ traderId });

      if (!isActionSuccessful(result)) {
        throw new Error(result.serverError ?? "Failed to unfollow trader");
      }

      return result.data;
    },
    onMutate: async () => {
      // Annuler toutes les queries en cours pour éviter les conflits
      await queryClient.cancelQueries({ queryKey: ["is-following"] });

      // Snapshot de la valeur précédente (utiliser userId si fourni pour matcher la query key)
      const queryKey = userId
        ? ["is-following", userId, traderId]
        : ["is-following", traderId];
      const previousIsFollowing = queryClient.getQueryData(queryKey);

      // Optimistic update : on met à jour immédiatement l'UI
      queryClient.setQueryData(queryKey, false);

      // Retourner le context avec la valeur précédente pour le rollback
      return { previousIsFollowing, queryKey };
    },
    onSuccess: (data) => {
      toast.success(data.message);
      // Invalider les queries pour rafraîchir les données depuis le serveur
      void queryClient.invalidateQueries({ queryKey: ["traders"] });
      void queryClient.invalidateQueries({ queryKey: ["following"] });
      void queryClient.invalidateQueries({ queryKey: ["is-following"] });
      void queryClient.invalidateQueries({ queryKey: ["trader-followers"] });
      void queryClient.invalidateQueries({ queryKey: ["trader-signals"] });
      // Force Server Component revalidation
      router.refresh();
      setShowUnfollowDialog(false);
    },
    onError: (error: Error, _variables, context) => {
      // En cas d'erreur, rollback à la valeur précédente
      if (context) {
        queryClient.setQueryData(context.queryKey, context.previousIsFollowing);
      }
      toast.error(error.message);
      setShowUnfollowDialog(false);
    },
  });

  const handleFollow = () => {
    followMutation.mutate();
  };

  const handleUnfollow = () => {
    setShowUnfollowDialog(true);
  };

  const confirmUnfollow = () => {
    unfollowMutation.mutate();
  };

  const isLoading = followMutation.isPending || unfollowMutation.isPending;

  return (
    <>
      {isFollowing ? (
        <Button
          onClick={handleUnfollow}
          disabled={isLoading}
          variant={variant}
          size={size}
          className={className}
        >
          {isLoading ? (
            <>Loading...</>
          ) : (
            <>
              <Check className="mr-2 size-4" />
              Following
            </>
          )}
        </Button>
      ) : (
        <Button
          onClick={handleFollow}
          disabled={isLoading}
          variant={variant}
          size={size}
          className={className}
        >
          {isLoading ? (
            <>Loading...</>
          ) : (
            <>
              <Plus className="mr-2 size-4" />
              Follow
            </>
          )}
        </Button>
      )}

      <AlertDialog
        open={showUnfollowDialog}
        onOpenChange={setShowUnfollowDialog}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Unfollow {traderName}</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to stop following {traderName}? You will no
              longer receive their trading signals.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={unfollowMutation.isPending}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmUnfollow}
              disabled={unfollowMutation.isPending}
            >
              {unfollowMutation.isPending ? "Unfollowing..." : "Unfollow"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

